%dw 2.0
var jsonPayload = if (typeOf(payload) ~= "String" or typeOf(payload) ~= "Binary") read(payload, "application/json") else payload
var filters = jsonPayload.filters default {}
var oscarsGt = filters."oscarsCount[gt]"
var oscarsMinValue = if (oscarsGt != null) (oscarsGt as Number) + 1 else filters.oscarsCountMin
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tns http://soap.web.calledweb.lovesoa.org/
---
{
    soapenv#Envelope: {
        soapenv#Header: {},
        soapenv#Body: {
            tns#searchMovies: {
                request: {
                    (filterName: filters.name default filters."name[eq]") if (filters.name? or filters."name[eq]"?),
                    (filterGenre: filters.genre default filters."genre[eq]") if (filters.genre? or filters."genre[eq]"?),
                    (filterMpaaRating: filters.mpaaRating default filters."mpaaRating[eq]") if (filters.mpaaRating? or filters."mpaaRating[eq]"?),
                    (filterOscarsCountMin: oscarsMinValue) if (oscarsMinValue != null),
                    (filterOscarsCountMax: filters.oscarsCountMax default filters."oscarsCount[lt]") if (filters.oscarsCountMax? or filters."oscarsCount[lt]"?),
                    (sortFields: jsonPayload.sort map ((item) -> item)) if jsonPayload.sort?,
                    page: jsonPayload.page default 0,
                    size: jsonPayload.size default 20
                }
            }
        }
    }
}

%dw 2.0
var jsonPayload = if (typeOf(payload) ~= "String" or typeOf(payload) ~= "Binary") read(payload, "application/json") else payload
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tns http://soap.web.calledweb.lovesoa.org/
---
{
    soapenv#Envelope: {
        soapenv#Header: {},
        soapenv#Body: {
            tns#createMovie: {
                request: {
                    (id: jsonPayload.id) if jsonPayload.id?,
                    name: jsonPayload.name,
                    coordinates: {
                        x: jsonPayload.coordinates.x,
                        y: jsonPayload.coordinates.y
                    },
                    oscarsCount: jsonPayload.oscarsCount,
                    (genre: jsonPayload.genre) if jsonPayload.genre?,
                    mpaaRating: jsonPayload.mpaaRating,
                    operator: {
                        name: jsonPayload.operator.name,
                        height: jsonPayload.operator.height,
                        (weight: jsonPayload.operator.weight) if jsonPayload.operator.weight?,
                        location: {
                            x: jsonPayload.operator.location.x,
                            (y: jsonPayload.operator.location.y) if jsonPayload.operator.location.y?,
                            z: jsonPayload.operator.location.z
                        }
                    }
                }
            }
        }
    }
}

