%dw 2.0
var jsonPayload = if (typeOf(payload) ~= "String" or typeOf(payload) ~= "Binary") read(payload, "application/json") else payload
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tns http://soap.web.calledweb.lovesoa.org/
fun mapMovieToSoap(m) = {
    (id: m.id) if m.id?,
    name: m.name,
    coordinates: {
        x: m.coordinates.x,
        y: m.coordinates.y
    },
    oscarsCount: m.oscarsCount,
    (genre: m.genre) if m.genre?,
    mpaaRating: m.mpaaRating,
    operator: {
        name: m.operator.name,
        height: m.operator.height,
        (weight: m.operator.weight) if m.operator.weight?,
        location: {
            x: m.operator.location.x,
            (y: m.operator.location.y) if m.operator.location.y?,
            z: m.operator.location.z
        }
    }
}
---
{
    soapenv#Envelope: {
        soapenv#Header: {},
        soapenv#Body: {
            tns#updateMovies: {
                request: {
                    (movies: jsonPayload.movies map ((movie) -> mapMovieToSoap(movie)))
                }
            }
        }
    }
}

